set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.apply_reward(p_member uuid, p_rewards jsonb, p_member_milestone bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_reward jsonb;
  v_kind   text;
BEGIN
  -- Walk the reward list and dispatch on kind. Each branch resolves its payload
  -- entry as a spec and persists the concrete outcome, so a future randomized
  -- reward computes its value here without any change upstream in record_progress.
  FOR v_reward IN SELECT * FROM jsonb_array_elements(p_rewards)
  LOOP
    v_kind := v_reward ->> 'kind';

    IF v_kind = 'paperclips' THEN
      -- The ledger is the only place a balance lives; this insert is the sole
      -- writer. The resolved amount is what gets stored, never the spec.
      INSERT INTO public.paperclip_ledger (member_id, amount, member_milestone_id)
      VALUES (p_member, (v_reward ->> 'amount')::bigint, p_member_milestone);
    ELSE
      RAISE EXCEPTION 'Unknown reward kind: %', v_kind;
    END IF;
  END LOOP;
END;
$function$
;

-- security_invoker restored by hand: db diff omits view reloptions, so the
-- generated create-or-replace would drop it and the view would read every
-- member's ledger rows instead of running the SELECT policy per-caller.
create or replace view "public"."member_paperclip_balance" with (security_invoker=true) as  SELECT paperclip_ledger.member_id,
    (COALESCE(sum(paperclip_ledger.amount), (0)::numeric))::bigint AS balance
   FROM public.paperclip_ledger
  GROUP BY paperclip_ledger.member_id;


CREATE OR REPLACE FUNCTION public.record_progress(p_member uuid, p_measure text, p_delta bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_old bigint;
  v_new bigint;
  v_ms  public.milestones%ROWTYPE;
  v_mm_id bigint;
BEGIN
  -- Ensure the tally row exists, then lock it for the rest of the transaction so
  -- two concurrent sources counting the same measure can't both read the same
  -- `old` and pay a milestone twice.
  INSERT INTO public.member_progress (member_id, measure, tally)
  VALUES (p_member, p_measure, 0)
  ON CONFLICT (member_id, measure) DO NOTHING;

  SELECT tally INTO v_old
    FROM public.member_progress
   WHERE member_id = p_member AND measure = p_measure
     FOR UPDATE;

  v_new := v_old + p_delta;

  UPDATE public.member_progress
     SET tally = v_new, updated_at = now()
   WHERE member_id = p_member AND measure = p_measure;

  -- Milestones whose threshold falls in (old, new] and that this member hasn't
  -- already earned. The half-open interval is the one-shot guard: a later call
  -- that pushes the tally further never re-crosses a threshold already below old.
  FOR v_ms IN
    SELECT m.*
      FROM public.milestones m
     WHERE m.measure = p_measure
       AND m.is_active
       AND m.threshold > v_old
       AND m.threshold <= v_new
       AND NOT EXISTS (
         SELECT 1 FROM public.member_milestones mm
          WHERE mm.member_id = p_member AND mm.milestone_id = m.id
       )
     ORDER BY m.threshold
  LOOP
    -- The unique (member_id, milestone_id) makes the insert the durable one-shot
    -- guard even under a race; DO NOTHING + null RETURNING means a concurrent
    -- winner already paid, so this call skips apply_reward.
    INSERT INTO public.member_milestones (member_id, milestone_id)
    VALUES (p_member, v_ms.id)
    ON CONFLICT (member_id, milestone_id) DO NOTHING
    RETURNING id INTO v_mm_id;

    IF v_mm_id IS NOT NULL THEN
      PERFORM public.apply_reward(p_member, v_ms.rewards, v_mm_id);
    END IF;
  END LOOP;
END;
$function$
;

